async function db(user, fn) {
  const connection = await pool.getConnection();
  try {
    await connection.execute(`BEGIN DBMS_SESSION.SET_IDENTIFIER(:user); END;`, { user });
    return await fn(connection);
  } finally { await connection.close(); }
}
function user(req) { const value = req.header('x-demo-user') || 'statewide_admin'; return validUsers.has(value) ? value : 'read_only_viewer'; }
