app.post('/api/watched-patterns/semantic-search', async (req,res) => {
  const query=String(req.body?.query||'').trim(), topK=Math.min(Math.max(Number(req.body?.topK)||6,1),12);
  if (!query) return res.status(400).json({error:'Describe a watched pattern to search.'});
  try {
    const started=Date.now(); const [vector]=await embedPatternTexts([query], 'SEARCH_QUERY');
    const result=await db(req.demoUser,c=>c.execute(`SELECT w.pattern_code,w.pattern_name,w.pattern_summary,w.why_watch,w.pattern_kind,w.pattern_status,w.case_ref,w.display_color,ROUND(1-VECTOR_DISTANCE(e.embedding,TO_VECTOR(:vector),COSINE),4) similarity_score FROM watched_pattern_embeddings e JOIN watched_crime_patterns w ON w.pattern_code=e.pattern_code WHERE w.active=1 AND w.activate_ui='Y' ORDER BY VECTOR_DISTANCE(e.embedding,TO_VECTOR(:vector),COSINE) FETCH FIRST :topK ROWS ONLY`, { vector: patternVectorLiteral(vector), topK }));
    res.json({query,model:PATTERN_EMBEDDING_MODEL,dimensions:PATTERN_EMBEDDING_DIMENSIONS,method:'VECTOR_DISTANCE(COSINE)',elapsed:Date.now()-started,results:result.rows,notice:'Semantic relevance ranks synthetic monitoring definitions only. It is not a finding, prediction, or evidence of a connection; analyst review is required.'});
  } catch(e) { console.error('Watched pattern semantic search error:',e);res.status(500).json({error:e.message}); }
});
