function crimeAskTopic(question) { const q=String(question||'').toLowerCase(); const topics=[
  {id:'demand',match:['demand','volume','category'],title:'Incident Demand Context',question:'Which incident categories have the highest recent authorised volume?',sql:`WITH b AS (SELECT MAX(occurred_at) max_occurred FROM secure_crime_incidents_v) SELECT cat.category_name AS incident_category,COUNT(*) AS incidents,SUM(CASE WHEN i.incident_status NOT IN ('resolved','closed_no_further_action') THEN 1 ELSE 0 END) AS active_records FROM secure_crime_incidents_v i JOIN incident_categories cat ON cat.category_id=i.category_id CROSS JOIN b WHERE i.occurred_at >= b.max_occurred-INTERVAL '30' DAY GROUP BY cat.category_name ORDER BY incidents DESC`,answer:(rows)=>`The current authorised 30-day view contains ${rows.reduce((sum,row)=>sum+Number(row.INCIDENTS||0),0).toLocaleString('en-AU')} synthetic incidents across ${rows.length} categories. The results show historical volume and active-record context only; they are not a crime forecast.`},
  {id:'quality',match:['quality','completeness','data quality'],title:'Incident Data Quality Signals',question:'What does record completeness look like across authorised incident categories?',sql:`SELECT cat.category_name AS incident_category,COUNT(*) AS incidents,SUM(CASE WHEN r.report_summary IS NOT NULL THEN 1 ELSE 0 END) AS reports_present,ROUND(AVG(CASE WHEN i.latitude IS NOT NULL AND i.longitude IS NOT NULL THEN 1 ELSE 0 END)*100,1) AS mapped_record_pct FROM secure_crime_incidents_v i JOIN incident_categories cat ON cat.category_id=i.category_id LEFT JOIN secure_incident_reports_v r ON r.incident_id=i.incident_id GROUP BY cat.category_name ORDER BY incidents DESC`,answer:(rows)=>`The quality view checks report and approximate-coordinate completeness for ${rows.length} authorised categories. It is a data-quality signal, not an assessment of incident validity or priority.`},
  {id:'logistics',match:['logistic','coverage','geograph','map','distributed'],title:'Geographic and Patrol Coverage',question:'How is authorised incident activity distributed across patrol areas?',sql:`SELECT p.area_name AS patrol_area,COUNT(*) AS incidents,COUNT(DISTINCT i.suburb) AS suburbs_represented,SUM(CASE WHEN i.incident_status NOT IN ('resolved','closed_no_further_action') THEN 1 ELSE 0 END) AS active_records FROM secure_crime_incidents_v i JOIN patrol_areas p ON p.patrol_area_id=i.patrol_area_id GROUP BY p.area_name ORDER BY incidents DESC`,answer:(rows)=>`The geographic coverage view returns ${rows.length} patrol areas visible to the active user. Counts are descriptive synthetic records, not a recommendation about patrol allocation.`},
  {id:'operations',match:['operation','active','status','workload'],title:'Active Incident Operations',question:'What is the authorised incident status mix?',sql:`SELECT incident_status,COUNT(*) AS incidents,COUNT(DISTINCT suburb) AS suburbs_represented FROM secure_crime_incidents_v GROUP BY incident_status ORDER BY incidents DESC`,answer:(rows)=>`The operations view summarises ${rows.length} authorised incident statuses. It is a record-management snapshot, not an operational direction.`},
  {id:'reports',match:['report','service request','request'],title:'Incident Reports',question:'Which categories have the most authorised incident reports?',sql:`SELECT cat.category_name AS incident_category,COUNT(r.report_id) AS incident_reports,ROUND(AVG(LENGTH(r.report_summary)),0) AS avg_summary_characters FROM secure_incident_reports_v r JOIN secure_crime_incidents_v i ON i.incident_id=r.incident_id JOIN incident_categories cat ON cat.category_id=i.category_id GROUP BY cat.category_name ORDER BY incident_reports DESC`,answer:()=>`The result shows authorised incident-report coverage by incident category.`},
  {id:'areas',match:['patrol area','care site','area','site'],title:'Patrol Areas',question:'Which patrol areas and suburbs are in my authorised data scope?',sql:`SELECT p.area_name AS patrol_area,COUNT(*) AS incidents,COUNT(DISTINCT i.suburb) AS suburbs_represented,COUNT(DISTINCT i.category_id) AS categories_represented FROM secure_crime_incidents_v i JOIN patrol_areas p ON p.patrol_area_id=i.patrol_area_id GROUP BY p.area_name ORDER BY patrol_area`,answer:(rows)=>`This answer reflects the current database security scope and its ${rows.length} visible patrol areas.`},
  {id:'trends',match:['trend','signal','recent','daily'],title:'Incident Signal Trends',question:'What is the recent authorised incident signal trend?',sql:`WITH b AS (SELECT MAX(occurred_at) max_occurred FROM secure_crime_incidents_v) SELECT TO_CHAR(TRUNC(i.occurred_at),'YYYY-MM-DD') AS incident_day,COUNT(*) AS incidents,SUM(CASE WHEN i.incident_status NOT IN ('resolved','closed_no_further_action') THEN 1 ELSE 0 END) AS active_records FROM secure_crime_incidents_v i CROSS JOIN b WHERE i.occurred_at >= b.max_occurred-INTERVAL '14' DAY GROUP BY TRUNC(i.occurred_at) ORDER BY incident_day`,answer:(rows)=>`The signal trend shows ${rows.length} observed daily buckets in the authorised history. It does not forecast future incident activity.`},
  {id:'pathways',match:['pathway','relationship','case','evidence'],title:'Case Relationships',question:'What relationship context is available across authorised case files?',sql:`SELECT c.case_ref,c.pattern_label,c.case_status,COUNT(DISTINCT l.incident_id) AS linked_incidents,COUNT(DISTINCT e.evidence_id) AS evidence_items,COUNT(DISTINCT pil.person_id) AS fictional_persons FROM case_files c JOIN case_incident_links l ON l.case_id=c.case_id JOIN secure_crime_incidents_v i ON i.incident_id=l.incident_id LEFT JOIN evidence_items e ON e.incident_id=i.incident_id LEFT JOIN person_incident_links pil ON pil.incident_id=i.incident_id GROUP BY c.case_ref,c.pattern_label,c.case_status ORDER BY linked_incidents DESC FETCH FIRST 20 ROWS ONLY`,answer:(rows)=>`${rows.length} authorised synthetic case contexts are shown, including linked incidents, evidence, and fictional person relationships.`}
]; return topics.find(topic=>topic.match.some(term=>q.includes(term)))||topics[0]; }
app.post('/api/ask', async (req,res) => { const question=String(req.body?.question||'').trim(),mode=String(req.body?.mode||'narrate'); if(!question)return res.status(400).json({error:'A question is required.'}); const topic=crimeAskTopic(question); try { const started=Date.now(); const preview=mode==='showsql'; const result=preview?{rows:[]} : await db(req.demoUser,c=>c.execute(topic.sql)); const rows=result.rows||[]; res.json({topic:topic.id,title:topic.title,question,mode,answer:preview?`The reviewed, read-only SQL template for ${topic.title} is shown below. Select Run query to execute it within the active data-security scope.`:topic.answer(rows),keyFindings:preview?[`Governed SQL template: ${topic.title}`,'Preview only — no SQL has been executed.','Synthetic descriptive data only — not for operational policing decisions.']:[`Governed SQL template: ${topic.title}`,`Active user scope returned ${rows.length} row${rows.length===1?'':'s'}.`,`Synthetic descriptive data only — not for operational policing decisions.`],sql:topic.sql,columns:rows[0]?Object.keys(rows[0]):[],rows,rowCount:rows.length,elapsed:Date.now()-started}); } catch(e){console.error('Ask Crime Data error:',e);res.status(500).json({error:e.message});} });
function crimeAgentTeam(topicId) { if(['logistics','areas'].includes(topicId))return 'LOGISTICS_AGENT'; if(['reports','operations','pathways'].includes(topicId))return 'REQUESTS_AGENT'; return 'SIGNALS_AGENT'; }
function crimeAgentLabel(team) { return ({SIGNALS_AGENT:'Signals Agent',REQUESTS_AGENT:'Requests Agent',LOGISTICS_AGENT:'Logistics Agent'})[team]||'CrimeData Agent'; }
