app.get('/api/persons/similar', async (req,res) => { const personRef=String(req.query.personRef||'').trim(),topK=Math.min(Math.max(Number(req.query.topK)||6,1),12); if(!personRef)return res.status(400).json({error:'personRef is required'}); try { const started=Date.now(); const r=await db(req.demoUser,c=>c.execute(`WITH selected_profile AS (SELECT e.embedding FROM person_narrative_embeddings e JOIN secure_persons_of_interest_v p ON p.person_id=e.person_id WHERE p.person_ref=:personRef) SELECT p.person_ref,p.display_name,p.alias_name,p.person_status,p.portrait_variant,p.portrait_asset_uri,p.portrait_alt_text,p.narrative_summary,ROUND(1-VECTOR_DISTANCE(e.embedding,s.embedding,COSINE),4) similarity_score FROM person_narrative_embeddings e JOIN secure_persons_of_interest_v p ON p.person_id=e.person_id CROSS JOIN selected_profile s WHERE p.person_ref <> :personRef ORDER BY VECTOR_DISTANCE(e.embedding,s.embedding,COSINE) FETCH FIRST :topK ROWS ONLY`,{personRef,topK})); res.json({personRef,model:NARRATIVE_MODEL,dimensions:NARRATIVE_DIMENSIONS,method:'VECTOR_DISTANCE(COSINE)',elapsed:Date.now()-started,results:r.rows,notice:'Narrative similarity across generated fictional profiles. Results are comparison leads, not findings.'}); } catch(e) { console.error('POI vector search error:',e); res.status(500).json({error:e.message}); } });
app.post('/api/persons/search/narrative', async (req,res) => { const query=String(req.body?.query||'').trim(),topK=Math.min(Math.max(Number(req.body?.topK)||6,1),12); if(query.length<3||query.length>2000)return res.status(400).json({error:'Enter a narrative query between 3 and 2,000 characters.'}); try { const started=Date.now(),embedding=vectorLiteral(await embedNarrative(query)); const r=await db(req.demoUser,c=>c.execute(`SELECT p.person_ref,p.display_name,p.alias_name,p.person_status,p.portrait_asset_uri,p.portrait_alt_text,p.narrative_summary,ROUND(1-VECTOR_DISTANCE(e.embedding,TO_VECTOR(:embedding),COSINE),4) similarity_score FROM person_narrative_embeddings e JOIN secure_persons_of_interest_v p ON p.person_id=e.person_id ORDER BY VECTOR_DISTANCE(e.embedding,TO_VECTOR(:embedding),COSINE) FETCH FIRST :topK ROWS ONLY`,{embedding,topK}));res.json({query,model:NARRATIVE_MODEL,dimensions:NARRATIVE_DIMENSIONS,method:'VECTOR_DISTANCE(COSINE)',elapsed:Date.now()-started,results:r.rows,notice:'Semantic ranking of generated fictional profile narratives; investigator review is required.'}); } catch(e) { console.error('POI narrative search error:',e);res.status(500).json({error:e.message}); } });
